mapper.select:
select 'TYPT' as systemCode, CASE WHEN chuzr.vc_kehmc='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN chuzr.vc_kehmc='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN chuzr.vc_kehmc='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN chuzr.vc_kehmc='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, -- chuzr.vc_kehmc as orgName, a.vc_cesztbh as contractCode, -- ht.vc_hetmc as contractName, a.vc_kehbh as clientCode, -- kh.vc_kehmc as clientName, b.nu_qix as periods, -- a.DT_YUJQZR as businessDate, max(bhsxjl.DT_CHENGFRQ) as planDate, sum(b.Dec_Zuj) as rentAmount, sum(b.dec_benj) as principalAmount, sum(b.dec_zux) as interestAmount, -- hlzt.vc_mingc as recaptureStatus, -- a.DEC_PLAN_IRR as sourceIrrRate, -- nvl(op_yuqts_f('1900-01-01',to_char(sysdate,'yyyy-mm-dd'), ht.vc_hetbh),0) as "逾期天数", sum(bhsxjl.DEC_JINGLL) as cashFlow from hxtypt.fm_jiaoyjg a left join hxtypt.fm_jiaoyjgxtbhsirr bhsxjl ON a.nu_id = bhsxjl.nu_jiaoyjgid left join hxtypt.fm_jiaoyjgzjjh b on a.nu_id = b.nu_jiaoyjgid AND b.dt_chengfrq = bhsxjl.dt_chengfrq left join hxtypt.bz_hetjbxx ht on a.vc_cesztbh = ht.vc_hetbh left join hxtypt.cm_jigkh kh on a.vc_kehbh = kh.vc_kehbh and kh.CH_YOUXBS = '0' left join hxtypt.ba_shujzd hlzt on b.vc_jihzt = hlzt.vc_zhi and hlzt.vc_fujdid = 'huilzt' left join hxtypt.bz_hetgf qyzt on qyzt.vc_hetbh = a.vc_cesztbh left join hxtypt.cm_jigkh chuzr on qyzt.vc_chuzr = chuzr.vc_kehbh and chuzr.CH_YOUXBS = '0' where a.vc_ceslx = '2'
and a.vc_cesztbh = #{params.contractCode}
group by a.vc_cesztbh, qyzt.vc_chuzr, to_char(b.DT_CHENGFRQ, 'yyyy-MM'), a.vc_kehbh, b.nu_qix order by a.vc_cesztbh, max(b.DT_CHENGFRQ)

select 'TYPT' as systemCode, CASE WHEN chuzr.vc_kehmc='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN chuzr.vc_kehmc='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN chuzr.vc_kehmc='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN chuzr.vc_kehmc='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, -- chuzr.vc_kehmc as orgName, a.vc_cesztbh as contractCode, -- ht.vc_hetmc as contractName, a.vc_kehbh as clientCode, -- kh.vc_kehmc as clientName, b.nu_qix as periods, -- a.DT_YUJQZR as businessDate, bhsxjl.DT_CHENGFRQ as planDate, b.Dec_Zuj as rentAmount, b.dec_benj as principalAmount, b.dec_zux as interestAmount, -- hlzt.vc_mingc as recaptureStatus, -- a.DEC_PLAN_IRR as sourceIrrRate, -- nvl(op_yuqts_f('1900-01-01',to_char(sysdate,'yyyy-mm-dd'), ht.vc_hetbh),0) as "逾期天数", bhsxjl.DEC_JINGLL as cashFlow from hxtypt.fm_jiaoyjg a left join hxtypt.fm_jiaoyjgxtbhsirr bhsxjl ON a.nu_id = bhsxjl.nu_jiaoyjgid left join hxtypt.fm_jiaoyjgzjjh b on a.nu_id = b.nu_jiaoyjgid AND b.dt_chengfrq = bhsxjl.dt_chengfrq left join hxtypt.bz_hetjbxx ht on a.vc_cesztbh = ht.vc_hetbh left join hxtypt.cm_jigkh kh on a.vc_kehbh = kh.vc_kehbh and kh.CH_YOUXBS = '0' left join hxtypt.ba_shujzd hlzt on b.vc_jihzt = hlzt.vc_zhi and hlzt.vc_fujdid = 'huilzt' left join hxtypt.bz_hetgf qyzt on qyzt.vc_hetbh = a.vc_cesztbh left join hxtypt.cm_jigkh chuzr on qyzt.vc_chuzr = chuzr.vc_kehbh and chuzr.CH_YOUXBS = '0' where a.vc_ceslx = '2'
and a.vc_cesztbh = #{params.contractCode}
order by a.vc_cesztbh, b.DT_CHENGFRQ

WITH table1 AS ( SELECT CONTRACT_ID FROM hxtypt.rpt_accmonth_firr_new GROUP BY contract_id HAVING TRUNC(max(PLAN_DATE)) >= TRUNC(TO_DATE('2023-01-01', 'YYYY-MM-DD')) ) SELECT CASE WHEN c.vc_kehmc='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN c.vc_kehmc='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN c.vc_kehmc='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN c.vc_kehmc='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, 'TYPT' as systemCode, -- 业务系统编号 a.contract_id as contractCode, --合同编号 a.plan_list as periods, -- 期项 max(a.plan_date) as planDate, -- 承付日期 sum(a.rent) as rentAmount, --租金 sum(a.net_flow) as cashFlow, --净流量 sum(a.naf_cut) as principalAmount, --本金 sum(a.interest) as interestAmount --租息 -- a.inter_day nu_interday, -- 当期承付日期与上期承付日期相差的天数 --a.interest_day dec_rilx, --日利息 -- a.interest_date dt_dangqzhyt, -- 当期最后一天 -- a.up_day nu_upday, --当期承付日期距上月最后一天的天数 -- a.down_day nu_downday, --当期承付日期距当月最后一天的天数 -- a.interest_cal dec_hanslx, -- 含税利息 -- a.interest_cal_aftertax dec_buhslx, --不含税利息 -- SYSDATE dt_chuangjsj -- 创建时间 FROM hxtypt.rpt_accmonth_firr_new a INNER JOIN table1 d ON a.CONTRACT_ID = d.CONTRACT_ID LEFT JOIN hxtypt.bz_hetgf b ON a.CONTRACT_ID = b.VC_HETBH LEFT JOIN hxtypt.cm_jigkh c on b.vc_chuzr = c.vc_kehbh and c.CH_YOUXBS = '0' WHERE c.vc_kehmc is not null
and a.contract_id = #{params.contractCode}
group by a.contract_id, a.plan_list, to_char(a.plan_date, 'yyyy-MM'), c.vc_kehmc

WITH table1 AS ( SELECT CONTRACT_ID FROM hxtypt.rpt_accmonth_firr_new GROUP BY contract_id HAVING TRUNC(max(PLAN_DATE)) >= TRUNC(TO_DATE('2023-01-01', 'YYYY-MM-DD')) ) SELECT CASE WHEN c.vc_kehmc='海通恒信国际融资租赁股份有限公司' THEN '01-C0001' WHEN c.vc_kehmc='海通恒信国际融资租赁（天津）有限公司' THEN '02-C0001' WHEN c.vc_kehmc='海通恒信小微融资租赁（上海）有限公司' THEN '80001' WHEN c.vc_kehmc='海通恒运融资租赁（上海）有限公司' THEN '30001' END AS orgId, 'TYPT' as systemCode, -- 业务系统编号 a.contract_id as contractCode, --合同编号 a.plan_list as periods, -- 期项 a.plan_date as planDate, -- 承付日期 a.rent as rentAmount, --租金 a.net_flow as cashFlow, --净流量 a.naf_cut as principalAmount, --本金 a.interest as interestAmount --租息 -- a.inter_day nu_interday, -- 当期承付日期与上期承付日期相差的天数 --a.interest_day dec_rilx, --日利息 -- a.interest_date dt_dangqzhyt, -- 当期最后一天 -- a.up_day nu_upday, --当期承付日期距上月最后一天的天数 -- a.down_day nu_downday, --当期承付日期距当月最后一天的天数 -- a.interest_cal dec_hanslx, -- 含税利息 -- a.interest_cal_aftertax dec_buhslx, --不含税利息 -- SYSDATE dt_chuangjsj -- 创建时间 FROM hxtypt.rpt_accmonth_firr_new a INNER JOIN table1 d ON a.CONTRACT_ID = d.CONTRACT_ID LEFT JOIN hxtypt.bz_hetgf b ON a.CONTRACT_ID = b.VC_HETBH LEFT JOIN hxtypt.cm_jigkh c on b.vc_chuzr = c.vc_kehbh and c.CH_YOUXBS = '0' WHERE c.vc_kehmc is not null
and a.contract_id = #{params.contractCode}
ORDER BY a.contract_id, a.plan_list
